const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});

const pdfKey = binaryKeys.find(k => {
  const b = item.binary[k];
  return (b.mimeType || '').includes('pdf') || (b.fileName || '').toLowerCase().endsWith('.pdf');
}) || binaryKeys[0];

if (!pdfKey) {
  throw new Error('Kein PDF-Anhang in der Mail gefunden.');
}

return [{
  json: { emailFrom: item.json.from, emailSubject: item.json.subject },
  binary: { data: item.binary[pdfKey] }
}];

const raw =
  $json?.content?.parts?.[0]?.text ||
  $json?.candidates?.[0]?.content?.parts?.[0]?.text ||
  $json?.text ||
  $json?.output ||
  '';

if (!raw) {
  return [{ json: { error: 'Keine Antwort von Gemini', rawResponse: JSON.stringify($json).substring(0, 400) } }];
}

let cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1) {
  return [{ json: { error: 'Kein JSON in KI-Antwort', raw: cleaned.substring(0, 400) } }];
}

cleaned = cleaned.slice(firstBrace, lastBrace + 1);
cleaned = cleaned.replace(/,(\s*[}\]])/g, '$1');

try {
  const parsed = JSON.parse(cleaned);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { error: 'JSON Parse Fehler: ' + e.message, raw: cleaned.substring(0, 400) } }];
}
